type Product = { id: string; sku: string; barcode: string; name: string; category: string; metal: string; stone: string; size: string; cost: number; price: number; stock: number; reorder: number };
type Customer = { id: string; name: string; phone: string; email: string; birthday: string; anniversary: string; preferences: string; notes: string; popia: boolean };
type Repair = { id: string; customer: string; item: string; condition: string; work: string; jeweller: string; cost: number; deposit: number; due: string; status: string; history: string[] };
type Layby = { id: string; customer: string; item: string; total: number; deposit: number; paid: number; due: string; status: string; payments: { date: string; amount: number }[] };
type Appraisal = { id: string; customer: string; item: string; metal: string; stone: string; weight: string; condition: string; valuation: number; date: string };
type Supplier = { id: string; name: string; contact: string; phone: string; categories: string; status: string };
type Sale = { id: string; date: string; customer: string; items: string; total: number; method: string; profit: number; category: string };
type Store = { products: Product[]; customers: Customer[]; repairs: Repair[]; laybys: Layby[]; appraisals: Appraisal[]; suppliers: Supplier[]; sales: Sale[]; quotes: Quote[]; invoices: Invoice[]; stockMovements: StockMovement[]; purchaseOrders: PurchaseOrder[]; auditLog: AuditEntry[]; communications: Communication[]; followUps: FollowUp[]; cashUps: CashUp[]; settings: { name: string; address: string; phone: string; vat: number; footer: string; invoiceFooter: string; quoteTerms: string } };

